/**
 * Builds an Idle Packet of `total_len` octets with the smallest header for the length and
 * the data field filled with `fill` (133.1 §4.1.2.3; EPP-005).
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`packet_len`) for 0 or more than 2³² − 1 octets,
 * `ALDIS_ERR_BUFFER_TOO_SMALL`; CABI-022 violations.
 *
 * # Safety
 * `out` is valid for `cap` octets; `out_len` is valid for one write; `err` is `NULL` or valid
 * for one write.
 */
int32_t aldis_epp_idle(size_t total_len,
                       uint8_t fill,
                       uint8_t *out,
                       size_t cap,
                       size_t *out_len,
                       aldis_error_detail_t *err);

/**
 * Encodes only the header of an Idle Packet of `total_len` octets (133.1 §4.1.2.3;
 * EPP-005, EPP-008). `packet_len` receives the Packet Length.
 *
 * # Errors
 * As [`aldis_epp_idle`].
 *
 * # Safety
 * `out` is valid for `cap` octets; `out_len` and `packet_len` are valid for one write each;
 * `err` is `NULL` or valid for one write.
 */
int32_t aldis_epp_idle_header(size_t total_len,
                              uint8_t *out,
                              size_t cap,
                              size_t *out_len,
                              uint32_t *packet_len,
                              aldis_error_detail_t *err);

/**
 * Checks a configuration: the minimum data length is at most the maximum, and the maximum
 * at most `ALDIS_EPP_MAX_DATA_LEN` (133.1 §5 Table 5-1; EPP-009, API-040).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_CONFIG` (`min_data_len`, `max_data_len`); CABI-022 violations.
 *
 * # Safety
 * `cfg` is valid for a read; `err` is `NULL` or valid for one write.
 */
int32_t aldis_epp_config_check(const aldis_epp_config_t *cfg, aldis_error_detail_t *err);

/**
 * Fills `limits` with the capacities of this build (CABI-030).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_FIELD` when `limits` is `NULL` or misaligned, or its `struct_size` is
 * smaller than `aldis_limits_t` (CABI-022).
 *
 * # Safety
 * `limits` is valid for a read of its `struct_size` and one write of `aldis_limits_t`.
 */
int32_t aldis_limits(aldis_limits_t *limits);

/**
 * Classifies the four OCF octets at `ocf` by bits 0–1 (CMN-010).
 *
 * `report` receives `ALDIS_OCF_CLCW`, `ALDIS_OCF_PROJECT_SPECIFIC`, or `ALDIS_OCF_SDLS_FSR`
 * (132.0 §4.1.5.4–5, 732.0 §4.1.5.4–5, 732.1 §4.1.5.2.1–2). Every four octets are an OCF, and
 * the CLCW is not decoded (CMN-011).
 *
 * # Errors
 * CABI-022 violations only: `ocf_len` other than `ALDIS_OCF_LEN`, `ocf` `NULL`, or `report`
 * `NULL` or misaligned.
 *
 * # Safety
 * `ocf` is valid for reads of `ocf_len` octets; `report` is valid for one write; `err` is
 * `NULL` or valid for one write.
 */
int32_t aldis_ocf_classify(const uint8_t *ocf,
                           size_t ocf_len,
                           uint32_t *report,
                           aldis_error_detail_t *err);

/**
 * Checks that the four OCF octets at `ocf` hold the report `report` (CMN-010).
 *
 * `report` is an `ALDIS_OCF_*` constant. A writer checks its report so before it places it in
 * a frame (132.0 §4.1.5.4–5, 732.0 §4.1.5.4–5, 732.1 §4.1.5.2.1–2).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_FIELD` naming `ALDIS_FIELD_OCF_TYPE_FLAG` when the Type Flag is not the
 * report's, or `ALDIS_FIELD_OCF_REPORT_USE` when bit 1 of a Type-2 Report is not, with the
 * expected and found bit; CABI-022 violations (no field): `ocf_len` other than
 * `ALDIS_OCF_LEN`, `ocf` `NULL`, or `report` not an `ALDIS_OCF_*` constant.
 *
 * # Safety
 * `ocf` is valid for reads of `ocf_len` octets; `err` is `NULL` or valid for one write.
 */
int32_t aldis_ocf_check(const uint8_t *ocf,
                        size_t ocf_len,
                        uint32_t report,
                        aldis_error_detail_t *err);

/**
 * The storage octets an `aldis_oid_generator_t` needs: `ALDIS_OID_GENERATOR_STORAGE_SIZE`
 * (CABI-031).
 */
size_t aldis_oid_generator_storage_size(void);

/**
 * The storage alignment an `aldis_oid_generator_t` needs: `ALDIS_OID_GENERATOR_STORAGE_ALIGN`
 * (CABI-031).
 */
size_t aldis_oid_generator_storage_align(void);

/**
 * Places an OID generator of the form `form` (`ALDIS_OID_FIBONACCI` or `ALDIS_OID_GALOIS`) in
 * `storage`, in its device start-up state (132.0 §4.1.4.6.2, Annex D; CMN-020, CMN-022;
 * CABI-031, CABI-032).
 *
 * # Errors
 * `ALDIS_ERR_BUFFER_TOO_SMALL` (with `needed`) for storage smaller than
 * `ALDIS_OID_GENERATOR_STORAGE_SIZE`; `ALDIS_ERR_INVALID_FIELD` for `NULL` or misaligned
 * storage, or a `form` that is no `ALDIS_OID_*` constant; CABI-022 violations.
 *
 * # Safety
 * `storage` is valid for writes of `storage_len` octets and outlives the handle; `out` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_oid_generator_init(void *storage,
                                 size_t storage_len,
                                 uint32_t form,
                                 aldis_oid_generator_t **out,
                                 aldis_error_detail_t *err);

/**
 * Fills the `len` octets at `out` with the next `len` octets of the OID sequence (CMN-023).
 *
 * The octets are MSB first, and the generator advances by exactly `len` octets (132.0
 * §4.1.4.6.2; CMN-020, CMN-021). The first 20 octets after `_init` are those of 132.0 Annex D.
 *
 * # Errors
 * `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations, including `out` overlapping the storage. On
 * error the generator is unchanged and `out` unwritten.
 *
 * # Safety
 * `h` is a handle from `aldis_oid_generator_init` whose storage is still valid, or detectably
 * invalid storage; `out` is valid for writes of `len` octets (or `NULL` with `len` 0); `err`
 * is `NULL` or valid for one write.
 */
int32_t aldis_oid_generator_fill(aldis_oid_generator_t *h,
                                 uint8_t *out,
                                 size_t len,
                                 aldis_error_detail_t *err);

/**
 * Releases an OID generator: later calls with `h` fail with `ALDIS_ERR_INVALID_HANDLE`
 * (CABI-032). An invalid handle is ignored.
 *
 * # Safety
 * `h` is `NULL`, a handle whose storage is still valid, or detectably invalid storage.
 */
void aldis_oid_generator_deinit(aldis_oid_generator_t *h);

/**
 * Decodes one Space Packet (133.0 §4.1; SPP-001…004, SPP-009, API-010, API-011, API-030).
 *
 * `bytes` may hold more than one packet: `out->packet_len` is the length of the first. The
 * data field is `bytes[data_offset .. data_offset + data_len]`.
 *
 * # Errors
 * `ALDIS_ERR_INCOMPLETE` (with `needed`) when `bytes` is shorter than the header or the
 * packet, `ALDIS_ERR_UNSUPPORTED_VERSION` (`packet_version`), and in strict mode
 * `ALDIS_ERR_INVALID_FIELD` (`secondary_header_flag`) for an Idle Packet with a secondary
 * header; CABI-022 violations.
 *
 * # Safety
 * `bytes` is valid for `len` octets (or `NULL` with `len` 0); `out` is valid for one write;
 * `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_decode(const uint8_t *bytes,
                         size_t len,
                         uint32_t mode,
                         aldis_spp_packet_t *out,
                         aldis_error_detail_t *err);

/**
 * The total length of the Space Packet that `prefix` begins, from its Primary Header alone
 * (133.0 §4.1.3.5; API-013, M2 plan D14).
 *
 * # Errors
 * `ALDIS_ERR_INCOMPLETE` with `needed` = 6 for a prefix shorter than the Primary Header,
 * `ALDIS_ERR_UNSUPPORTED_VERSION` (`packet_version`); CABI-022 violations.
 *
 * # Safety
 * `prefix` is valid for `prefix_len` octets (or `NULL` with `prefix_len` 0); `out_len` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_peek_length(const uint8_t *prefix,
                              size_t prefix_len,
                              size_t *out_len,
                              aldis_error_detail_t *err);

/**
 * Encodes a Space Packet from its fields, secondary header, and User Data Field in one call
 * (133.0 §4.1; SPP-005, SPP-006, API-020…022).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_FIELD` for an empty data field (`data_field`) or an Idle Packet with a
 * secondary header (`secondary_header_flag`), `ALDIS_ERR_OUT_OF_RANGE` (`packet_len`) above
 * the Maximum Packet Length, `ALDIS_ERR_BUFFER_TOO_SMALL` (with `needed`), the errors of the
 * fields (`apid`, `sequence_count`); CABI-022 violations, including `out` overlapping an input.
 *
 * # Safety
 * `cfg` and `fields` are valid for reads; `secondary` and `user` are valid for their lengths
 * (or `NULL` with length 0); `out` is valid for `cap` octets; `out_len` is valid for one write;
 * `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_encode(const aldis_spp_config_t *cfg,
                         const aldis_spp_fields_t *fields,
                         const uint8_t *secondary,
                         size_t secondary_len,
                         const uint8_t *user,
                         size_t user_len,
                         uint8_t *out,
                         size_t cap,
                         size_t *out_len,
                         aldis_error_detail_t *err);

/**
 * Starts a two-phase write (133.0 §4.1; SPP-005, API-023, M2 plan D4).
 *
 * Checks the arguments, writes an unfinished Primary Header (version `111`, which no decoder
 * accepts), and reports where the caller fills in the secondary header and the User Data Field.
 *
 * No state is kept: [`aldis_spp_writer_finish`] takes the same arguments again. The buffer
 * holds no valid packet until it is finished (API-023).
 *
 * # Errors
 * As [`aldis_spp_encode`], with the packet length taken as `6 + secondary_len + max_user_len`.
 *
 * # Safety
 * `cfg` and `fields` are valid for reads; `out` is valid for `cap` octets; `layout` is valid
 * for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_writer_begin(const aldis_spp_config_t *cfg,
                               const aldis_spp_fields_t *fields,
                               size_t secondary_len,
                               size_t max_user_len,
                               uint8_t *out,
                               size_t cap,
                               aldis_spp_writer_layout_t *layout,
                               aldis_error_detail_t *err);

/**
 * Finishes a two-phase write begun with the same arguments: writes the final Primary Header
 * for `user_len` octets of user data and returns the packet length (133.0 §4.1; SPP-005,
 * API-021, API-023).
 *
 * # Errors
 * As [`aldis_spp_writer_begin`], and `ALDIS_ERR_OUT_OF_RANGE` (`user_len`) above
 * `max_user_len`.
 *
 * # Safety
 * As [`aldis_spp_writer_begin`]; `out_len` is valid for one write.
 */
int32_t aldis_spp_writer_finish(const aldis_spp_config_t *cfg,
                                const aldis_spp_fields_t *fields,
                                size_t secondary_len,
                                size_t max_user_len,
                                size_t user_len,
                                uint8_t *out,
                                size_t cap,
                                size_t *out_len,
                                aldis_error_detail_t *err);

/**
 * Builds an Idle Packet of `total_len` octets: APID 2047, Sequence Flags `11`, and the data
 * field filled by repeating `pattern` (one octet 0x00 when empty) (133.0 §4.1.3.3.4.4,
 * §4.1.4.3.4; SPP-010).
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`packet_len`) below 7 or above the Maximum Packet Length or
 * (`sequence_count`) above 16383, `ALDIS_ERR_BUFFER_TOO_SMALL`; CABI-022 violations.
 *
 * # Safety
 * `cfg` is valid for a read; `pattern` is valid for `pattern_len` octets (or `NULL` with 0);
 * `out` is valid for `cap` octets; `out_len` is valid for one write; `err` is `NULL` or valid
 * for one write.
 */
int32_t aldis_spp_idle(const aldis_spp_config_t *cfg,
                       size_t total_len,
                       uint16_t sequence_count,
                       const uint8_t *pattern,
                       size_t pattern_len,
                       uint8_t *out,
                       size_t cap,
                       size_t *out_len,
                       aldis_error_detail_t *err);

/**
 * Encodes one octet string as a packet of the Octet String service (133.0 §3.4, §4.2.2;
 * SPP-012).
 *
 * The packet is unsegmented, carries the count `sequence_count` and the Secondary Header
 * Flag `secondary_header_indicator`; `next_count` receives the count of the next packet.
 *
 * # Errors
 * `ALDIS_ERR_INVALID_FIELD` for APID 2047 (`apid`) or an empty octet string (`data_field`),
 * `ALDIS_ERR_OUT_OF_RANGE` (`packet_len`, `apid`, `sequence_count`),
 * `ALDIS_ERR_BUFFER_TOO_SMALL`; CABI-022 violations. On error `next_count` is not written.
 *
 * # Safety
 * `cfg` is valid for a read; `octets` is valid for `octets_len` octets; `out` is valid for
 * `cap` octets; `out_len` and `next_count` are valid for one write; `err` is `NULL` or valid
 * for one write.
 */
int32_t aldis_spp_octet_string_encode(const aldis_spp_config_t *cfg,
                                      uint8_t packet_type,
                                      uint16_t apid,
                                      uint16_t sequence_count,
                                      bool secondary_header_indicator,
                                      const uint8_t *octets,
                                      size_t octets_len,
                                      uint8_t *out,
                                      size_t cap,
                                      size_t *out_len,
                                      uint16_t *next_count,
                                      aldis_error_detail_t *err);

/**
 * The Packet Sequence Count after `count`, modulo 16384 (133.0 §4.1.3.4.3.3; SPP-011).
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`sequence_count`) above 16383; CABI-022 violations.
 *
 * # Safety
 * `next` is valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_sequence_count_next(uint16_t count, uint16_t *next, aldis_error_detail_t *err);

/**
 * Checks a configuration: the Maximum Packet Length is 7 to 65 542 octets (133.0 §5.2
 * Table 5-1; SPP-005, API-040).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_CONFIG` (`max_packet_len`); CABI-022 violations.
 *
 * # Safety
 * `cfg` is valid for a read; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_config_check(const aldis_spp_config_t *cfg, aldis_error_detail_t *err);

/**
 * Decodes one Space Packet and splits its data field by the APID's secondary header layout
 * (133.0 §4.1.4.2; SPP-007, SPP-008, CABI-012).
 *
 * The layout is an opaque header, or a Time Code Field decoded with `aldis-time` followed by
 * Ancillary Data.
 *
 * # Errors
 * The errors of [`aldis_spp_decode`]; `ALDIS_ERR_INVALID_FIELD` (`secondary_header_flag`) when
 * the flag disagrees with the layout, or (`time_code_id`) for a P-field of another time code;
 * `ALDIS_ERR_LENGTH_MISMATCH` (`secondary_header`) for a data field shorter than the
 * secondary header; `ALDIS_ERR_INVALID_CONFIG` (`time_code`) for a CCS or agency-defined
 * layout; the errors of the time code; CABI-022 violations.
 *
 * # Safety
 * `bytes` is valid for `len` octets (or `NULL` with 0); `layout` is valid for a read; `out` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_split(const uint8_t *bytes,
                        size_t len,
                        uint32_t mode,
                        const aldis_spp_secondary_layout_t *layout,
                        aldis_spp_split_t *out,
                        aldis_error_detail_t *err);

/**
 * The storage octets an `aldis_spp_tracker_t` needs: `ALDIS_SPP_TRACKER_STORAGE_SIZE`
 * (CABI-031).
 */
size_t aldis_spp_tracker_storage_size(void);

/**
 * The storage alignment an `aldis_spp_tracker_t` needs: `ALDIS_SPP_TRACKER_STORAGE_ALIGN`
 * (CABI-031).
 */
size_t aldis_spp_tracker_storage_align(void);

/**
 * Places an empty Packet Sequence Count tracker in `storage` (SPP-011; CABI-031, CABI-032).
 *
 * # Errors
 * `ALDIS_ERR_BUFFER_TOO_SMALL` (with `needed`) for storage smaller than
 * `ALDIS_SPP_TRACKER_STORAGE_SIZE`; `ALDIS_ERR_INVALID_FIELD` for `NULL` or misaligned storage;
 * `ALDIS_ERR_INVALID_CONFIG` for a capacity of 0 and `ALDIS_ERR_CAPACITY_EXCEEDED` for one
 * above `ALDIS_SPP_TRACKER_MAX_APIDS`; CABI-022 violations.
 *
 * # Safety
 * `storage` is valid for writes of `storage_len` octets and outlives the handle; `cfg` is
 * valid for a read; `out` is valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_tracker_init(void *storage,
                               size_t storage_len,
                               const aldis_spp_tracker_config_t *cfg,
                               aldis_spp_tracker_t **out,
                               aldis_error_detail_t *err);

/**
 * Classifies the count `count` of `apid` against the last one tracked (133.0 §4.1.3.4.3.3–4;
 * SPP-011, CMN-031).
 *
 * # Errors
 * `ALDIS_ERR_CAPACITY_EXCEEDED` (`apid`, with the capacity) for a new APID when the tracker is
 * full; `ALDIS_ERR_OUT_OF_RANGE` (`apid`, `sequence_count`); `ALDIS_ERR_INVALID_HANDLE`;
 * CABI-022 violations. On error the tracker is unchanged.
 *
 * # Safety
 * `h` is a handle from `aldis_spp_tracker_init` whose storage is still valid, or detectably
 * invalid storage; `out` is valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_tracker_track(aldis_spp_tracker_t *h,
                                uint16_t apid,
                                uint16_t count,
                                aldis_spp_tracked_t *out,
                                aldis_error_detail_t *err);

/**
 * Stops tracking `apid`; `forgot` says whether it was tracked (SPP-011).
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`apid`); `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations.
 *
 * # Safety
 * As for [`aldis_spp_tracker_track`]; `forgot` is valid for one write.
 */
int32_t aldis_spp_tracker_forget(aldis_spp_tracker_t *h,
                                 uint16_t apid,
                                 bool *forgot,
                                 aldis_error_detail_t *err);

/**
 * The last count tracked for `apid`: `known` is false when it is not tracked (SPP-011).
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`apid`); `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations.
 *
 * # Safety
 * As for [`aldis_spp_tracker_track`]; `known` and `count` are valid for one write each.
 */
int32_t aldis_spp_tracker_last(aldis_spp_tracker_t *h,
                               uint16_t apid,
                               bool *known,
                               uint16_t *count,
                               aldis_error_detail_t *err);

/**
 * The number of APIDs tracked (SPP-011).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations.
 *
 * # Safety
 * As for [`aldis_spp_tracker_track`]; `len` is valid for one write.
 */
int32_t aldis_spp_tracker_len(aldis_spp_tracker_t *h, size_t *len, aldis_error_detail_t *err);

/**
 * Releases a tracker: later calls with `h` fail with `ALDIS_ERR_INVALID_HANDLE` (CABI-032).
 * An invalid handle is ignored.
 *
 * # Safety
 * `h` is `NULL`, a handle whose storage is still valid, or detectably invalid storage.
 */
void aldis_spp_tracker_deinit(aldis_spp_tracker_t *h);

/**
 * The storage octets an `aldis_spp_segmenter_t` needs: `ALDIS_SPP_SEGMENTER_STORAGE_SIZE`
 * (CABI-031).
 */
size_t aldis_spp_segmenter_storage_size(void);

/**
 * The storage alignment an `aldis_spp_segmenter_t` needs: `ALDIS_SPP_SEGMENTER_STORAGE_ALIGN`
 * (CABI-031).
 */
size_t aldis_spp_segmenter_storage_align(void);

/**
 * Places a segmenter for `sdu` in `storage` (133.0 §4.1.3.4.2; SPP-013; CABI-031, CABI-032).
 *
 * The segmenter keeps only the SDU's length and its position: every call to
 * [`aldis_spp_segmenter_next`] takes the same SDU again (API-060).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_FIELD` for an empty SDU (`sdu`) or APID 2047 (`apid`),
 * `ALDIS_ERR_OUT_OF_RANGE` (`max_user_len`) for 0 or (`apid`) above 2047,
 * `ALDIS_ERR_INVALID_CONFIG` (`max_packet_len`); the storage errors of
 * [`aldis_spp_tracker_init`]; CABI-022 violations.
 *
 * # Safety
 * `storage` is valid for writes of `storage_len` octets and outlives the handle; `spp` and
 * `cfg` are valid for reads; `sdu` is valid for `sdu_len` octets; `out` is valid for one
 * write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_segmenter_init(void *storage,
                                 size_t storage_len,
                                 const aldis_spp_config_t *spp,
                                 const aldis_spp_segmenter_config_t *cfg,
                                 const uint8_t *sdu,
                                 size_t sdu_len,
                                 aldis_spp_segmenter_t **out,
                                 aldis_error_detail_t *err);

/**
 * Encodes the next segment of `sdu` with the count `sequence_count` and the secondary header
 * `secondary` (empty for none) (133.0 §4.1.3.4.2; SPP-013).
 *
 * `out_len` is 0 when the SDU is done and no packet was written; otherwise `next_count` is the
 * count of the next packet.
 *
 * # Errors
 * `ALDIS_ERR_LENGTH_MISMATCH` (`sdu`) for an SDU of another length than at `_init`,
 * `ALDIS_ERR_OUT_OF_RANGE` (`packet_len`, `sequence_count`), `ALDIS_ERR_BUFFER_TOO_SMALL`;
 * `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations, including `out` overlapping an input or the
 * storage. On error nothing changes.
 *
 * # Safety
 * `h` is as for [`aldis_spp_tracker_track`]; `sdu` and `secondary` are valid for their lengths;
 * `out` is valid for `cap` octets; `out_len` and `next_count` are valid for one write each;
 * `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_segmenter_next(aldis_spp_segmenter_t *h,
                                 const uint8_t *sdu,
                                 size_t sdu_len,
                                 uint16_t sequence_count,
                                 const uint8_t *secondary,
                                 size_t secondary_len,
                                 uint8_t *out,
                                 size_t cap,
                                 size_t *out_len,
                                 uint16_t *next_count,
                                 aldis_error_detail_t *err);

/**
 * SDU octets not yet written (133.0 §4.1.3.4.2; SPP-013).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations.
 *
 * # Safety
 * As for [`aldis_spp_tracker_track`]; `remaining` is valid for one write.
 */
int32_t aldis_spp_segmenter_remaining(aldis_spp_segmenter_t *h,
                                      size_t *remaining,
                                      aldis_error_detail_t *err);

/**
 * Releases a segmenter (CABI-032); an invalid handle is ignored.
 *
 * # Safety
 * As for [`aldis_spp_tracker_deinit`].
 */
void aldis_spp_segmenter_deinit(aldis_spp_segmenter_t *h);

/**
 * The storage octets an `aldis_spp_reassembler_t` needs:
 * `ALDIS_SPP_REASSEMBLER_STORAGE_SIZE` (CABI-031).
 */
size_t aldis_spp_reassembler_storage_size(void);

/**
 * The storage alignment an `aldis_spp_reassembler_t` needs:
 * `ALDIS_SPP_REASSEMBLER_STORAGE_ALIGN` (CABI-031).
 */
size_t aldis_spp_reassembler_storage_align(void);

/**
 * Places a reassembler for `apid` in `storage` (133.0 §4.1.3.4.2; SPP-013; CABI-031,
 * CABI-032).
 *
 * The reassembler keeps no buffer: every push takes the same reassembly buffer (API-060).
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`apid`); the storage errors of [`aldis_spp_tracker_init`];
 * CABI-022 violations.
 *
 * # Safety
 * `storage` is valid for writes of `storage_len` octets and outlives the handle; `out` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_reassembler_init(void *storage,
                                   size_t storage_len,
                                   uint16_t apid,
                                   aldis_spp_reassembler_t **out,
                                   aldis_error_detail_t *err);

/**
 * Decodes one Space Packet, splits its data field by `layout`, and pushes its User Data Field
 * into the reassembly buffer `buf` (133.0 §4.1.3.4.2; SPP-013).
 *
 * A completed SDU is `buf[0 .. out->sdu_len]` until the next push.
 *
 * # Errors
 * The errors of `aldis_spp_split`; `ALDIS_ERR_INVALID_FIELD` (`apid`) for a packet of another
 * APID; `ALDIS_ERR_BUFFER_TOO_SMALL` (with `needed`) for a buffer shorter than the SDU in
 * progress; `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations, including `buf` overlapping the
 * packet or the storage. On error the reassembler is unchanged.
 *
 * # Safety
 * `h` is as for [`aldis_spp_tracker_track`]; `packet` is valid for `packet_len` octets;
 * `layout` is valid for a read; `buf` is valid for `buf_len` octets and holds what earlier
 * pushes wrote; `out` is valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_spp_reassembler_push(aldis_spp_reassembler_t *h,
                                   const uint8_t *packet,
                                   size_t packet_len,
                                   uint32_t mode,
                                   const aldis_spp_secondary_layout_t *layout,
                                   uint8_t *buf,
                                   size_t buf_len,
                                   aldis_spp_reassembly_t *out,
                                   aldis_error_detail_t *err);

/**
 * Discards any partial SDU and forgets the last count (133.0 §4.1.3.4.2; SPP-013).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations.
 *
 * # Safety
 * As for [`aldis_spp_tracker_track`].
 */
int32_t aldis_spp_reassembler_reset(aldis_spp_reassembler_t *h, aldis_error_detail_t *err);

/**
 * Whether a partial SDU is in progress (133.0 §4.1.3.4.2; SPP-013).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_HANDLE`; CABI-022 violations.
 *
 * # Safety
 * As for [`aldis_spp_tracker_track`]; `assembling` is valid for one write.
 */
int32_t aldis_spp_reassembler_is_assembling(aldis_spp_reassembler_t *h,
                                            bool *assembling,
                                            aldis_error_detail_t *err);

/**
 * Releases a reassembler (CABI-032); an invalid handle is ignored.
 *
 * # Safety
 * As for [`aldis_spp_tracker_deinit`].
 */
void aldis_spp_reassembler_deinit(aldis_spp_reassembler_t *h);

/**
 * Decodes a time code that starts with its P-field (301.0 §3.1; TIME-001…006, TIME-010…030,
 * API-030).
 *
 * # Errors
 * `ALDIS_ERR_INCOMPLETE` (with `needed`), `ALDIS_ERR_MALFORMED` (`pfield`) for an extension
 * chain longer than 8 octets, `ALDIS_ERR_RESERVED_VALUE` in strict mode (`time_code_id`,
 * `pfield`, `subms`, `subsecond_octets`, `day_of_year`), and the value errors of each code
 * (`ms_of_day`, `subms`, BCD digits); CABI-022 violations.
 *
 * # Safety
 * `bytes` is valid for `len` octets (or `NULL` with 0); `out` is valid for one write; `err` is
 * `NULL` or valid for one write.
 */
int32_t aldis_time_decode(const uint8_t *bytes,
                          size_t len,
                          uint32_t mode,
                          aldis_time_decoded_t *out,
                          aldis_error_detail_t *err);

/**
 * Decodes the T-field of a time code whose format is implicit (301.0 §3.1; TIME-003).
 *
 * # Errors
 * As [`aldis_time_decode`], and the errors of the format; CABI-022 violations.
 *
 * # Safety
 * `bytes` is valid for `len` octets (or `NULL` with 0); `format` is valid for a read; `out` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_time_decode_implicit(const uint8_t *bytes,
                                   size_t len,
                                   const aldis_time_format_t *format,
                                   uint32_t mode,
                                   aldis_time_decoded_t *out,
                                   aldis_error_detail_t *err);

/**
 * Encodes a time code, with its P-field when `include_pfield` (301.0 §3; TIME-001…033,
 * API-020…022).
 *
 * # Errors
 * The errors of the format and value: `ALDIS_ERR_OUT_OF_RANGE` naming the field (`coarse`,
 * `fine`, `cds_day`, `ms_of_day`, `subms`, `year`, `month`, `day`, `day_of_year`, `hour`,
 * `minute`, `second`, `subsecond`), `ALDIS_ERR_INVALID_FIELD` (`subms`, `date`),
 * `ALDIS_ERR_LENGTH_MISMATCH` (`tfield`); `ALDIS_ERR_BUFFER_TOO_SMALL`; CABI-022 violations.
 *
 * # Safety
 * `format` and `value` are valid for reads; `out` is valid for `cap` octets; `out_len` is valid
 * for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_time_encode(const aldis_time_format_t *format,
                          const aldis_time_value_t *value,
                          bool include_pfield,
                          uint8_t *out,
                          size_t cap,
                          size_t *out_len,
                          aldis_error_detail_t *err);

/**
 * Parses the P-field that `bytes` begins with (301.0 §3.1.1; TIME-001, TIME-005).
 *
 * # Errors
 * `ALDIS_ERR_INCOMPLETE` (with `needed`), `ALDIS_ERR_MALFORMED` (`pfield`); CABI-022
 * violations.
 *
 * # Safety
 * `bytes` is valid for `len` octets (or `NULL` with 0); `out` is valid for one write; `err` is
 * `NULL` or valid for one write.
 */
int32_t aldis_time_pfield_parse(const uint8_t *bytes,
                                size_t len,
                                aldis_time_pfield_t *out,
                                aldis_error_detail_t *err);

/**
 * The P-field octets of a format (301.0 §3.1.1; TIME-001, TIME-005).
 *
 * # Errors
 * The errors of the format, `ALDIS_ERR_BUFFER_TOO_SMALL`; CABI-022 violations.
 *
 * # Safety
 * `format` is valid for a read; `out` is valid for `cap` octets; `out_len` is valid for one
 * write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_time_format_pfield(const aldis_time_format_t *format,
                                 uint8_t *out,
                                 size_t cap,
                                 size_t *out_len,
                                 aldis_error_detail_t *err);

/**
 * The T-field length of a format in octets (301.0 §3; TIME-003).
 *
 * # Errors
 * The errors of the format; CABI-022 violations.
 *
 * # Safety
 * `format` is valid for a read; `t_len` is valid for one write; `err` is `NULL` or valid for
 * one write.
 */
int32_t aldis_time_format_t_len(const aldis_time_format_t *format,
                                size_t *t_len,
                                aldis_error_detail_t *err);

/**
 * CUC time as seconds and nanoseconds, the fraction truncated (301.0 §3.2; TIME-011). Only
 * `coarse`, `fine`, and `fine_len` of `value` are read.
 *
 * The basic time unit is taken to be the second (301.0 §1.2, §3.2.1); for a Level 2 code the
 * result is the time in seconds only if the agency's unit is the second.
 *
 * # Errors
 * CABI-022 violations, including a `fine_len` above 10 or fine octets set from `fine_len` on.
 *
 * # Safety
 * `value` is valid for a read; `seconds` and `nanoseconds` are valid for one write each; `err`
 * is `NULL` or valid for one write.
 */
int32_t aldis_time_cuc_to_ns(const aldis_time_value_t *value,
                             uint64_t *seconds,
                             uint32_t *nanoseconds,
                             aldis_error_detail_t *err);

/**
 * CUC time of a CUC format for seconds and nanoseconds, the fraction rounded down to the
 * format's resolution, so the coarse time is always `seconds` (301.0 §3.2; TIME-011, TIME-012,
 * OI-40).
 *
 * The basic time unit is taken to be the second (301.0 §1.2, §3.2.1); for a Level 2 format the
 * code is right only if the agency's unit is the second.
 *
 * # Errors
 * `ALDIS_ERR_OUT_OF_RANGE` (`nanoseconds`) at 10⁹ or more, or (`coarse`) when the seconds do
 * not fit; the errors of the format; CABI-022 violations, including a format that is not CUC.
 *
 * # Safety
 * `format` is valid for a read; `out` is valid for one write; `err` is `NULL` or valid for one
 * write.
 */
int32_t aldis_time_cuc_from_ns(const aldis_time_format_t *format,
                               uint64_t seconds,
                               uint32_t nanoseconds,
                               aldis_time_value_t *out,
                               aldis_error_detail_t *err);

/**
 * Parses a complete ASCII code A or B; `text` must be exactly the code, without a NUL
 * (301.0 §3.5.1.1–2; TIME-031).
 *
 * # Errors
 * `ALDIS_ERR_MALFORMED` for a separator, length, or trailing-octet problem,
 * `ALDIS_ERR_INVALID_FIELD` naming a subfield that holds a non-digit, `ALDIS_ERR_OUT_OF_RANGE`
 * naming a value outside its range, or `fraction` for more digits than `options` allow;
 * CABI-022 violations.
 *
 * # Safety
 * `text` is valid for `len` octets (or `NULL` with 0); `options` is valid for a read; `out` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_time_ascii_parse(const uint8_t *text,
                               size_t len,
                               const aldis_time_ascii_options_t *options,
                               aldis_time_ascii_t *out,
                               aldis_error_detail_t *err);

/**
 * Writes a complete ASCII code A or B, without a NUL (301.0 §3.5.1; TIME-031, API-022).
 *
 * # Errors
 * The errors of the fields (`year`, `month`, `day`, `day_of_year`, `hour`, `minute`,
 * `second`, `fraction`, `fraction_digits`), `ALDIS_ERR_BUFFER_TOO_SMALL` (with `needed`);
 * CABI-022 violations.
 *
 * # Safety
 * `time` is valid for a read; `out` is valid for `cap` octets; `out_len` is valid for one
 * write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_time_ascii_format(const aldis_time_ascii_t *time,
                                uint8_t *out,
                                size_t cap,
                                size_t *out_len,
                                aldis_error_detail_t *err);

/**
 * The length in octets that [`aldis_time_ascii_format`] writes for `time`, at most
 * `ALDIS_TIME_MAX_ASCII_LEN` (301.0 §3.5.1; TIME-031).
 *
 * # Errors
 * The errors of the fields; CABI-022 violations.
 *
 * # Safety
 * `time` is valid for a read; `out_len` is valid for one write; `err` is `NULL` or valid for
 * one write.
 */
int32_t aldis_time_ascii_encoded_len(const aldis_time_ascii_t *time,
                                     size_t *out_len,
                                     aldis_error_detail_t *err);

/**
 * Parses a complete ASCII code or any subset of 301.0 §3.5.1.3; `text` must be exactly the
 * code (TIME-032).
 *
 * # Errors
 * `ALDIS_ERR_MALFORMED` for a shape §5.1 of time-codes.md does not allow,
 * `ALDIS_ERR_INVALID_FIELD`, `ALDIS_ERR_OUT_OF_RANGE` as [`aldis_time_ascii_parse`];
 * CABI-022 violations.
 *
 * # Safety
 * `text` is valid for `len` octets (or `NULL` with 0); `options` is valid for a read; `out` is
 * valid for one write; `err` is `NULL` or valid for one write.
 */
int32_t aldis_time_ascii_subset_parse(const uint8_t *text,
                                      size_t len,
                                      const aldis_time_ascii_options_t *options,
                                      aldis_time_ascii_subset_t *out,
                                      aldis_error_detail_t *err);

/**
 * Converts a CDS, CCS, or ASCII time to another of the three through UTC, exactly where the
 * target's resolution allows and truncated otherwise (301.0 §3.3–3.5; TIME-033).
 *
 * # Errors
 * `ALDIS_ERR_INVALID_CONFIG` (`agency_epoch`) for an agency-epoch CDS code without
 * `has_agency_epoch`; `ALDIS_ERR_OUT_OF_RANGE` (`cds_day`) before the CDS epoch, (`second`) for
 * a leap second that is not 23:59:60, (`year`) outside 1 to 9999; the errors of the formats and
 * values; CABI-022 violations.
 *
 * # Safety
 * `from` and `cfg` are valid for reads; `out` is valid for one write; `err` is `NULL` or valid
 * for one write.
 */
int32_t aldis_time_convert(const aldis_time_instant_t *from,
                           const aldis_time_convert_config_t *cfg,
                           aldis_time_instant_t *out,
                           aldis_error_detail_t *err);

